// @exec: {"yield_time_ms":65000}
const deadline = Date.now() + 60000;
let result = await tools.exec_command({"cmd":"echo tests ran","yield_time_ms":30000});
let output = result.output ?? '';
while (result.exit_code === undefined && result.session_id !== undefined && Date.now() < deadline) {
  result = await tools.write_stdin({ session_id: result.session_id, chars: '', yield_time_ms: Math.min(300000, Math.max(1000, deadline - Date.now())) });
  output += result.output ?? '';
}
text({ ...result, output });

